"""Date-window membership for the date_window fixture."""

from __future__ import annotations

from datetime import datetime


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    Validates all dates in strict ISO format (YYYY-MM-DD) and checks if
    target_date falls within any of the provided windows (inclusive boundaries).
    """
    # Parse and validate target_date
    target = _parse_date(target_date)

    # Check each window
    for start_str, end_str in windows:
        start = _parse_date(start_str)
        end = _parse_date(end_str)

        # Validate that start <= end
        if start > end:
            raise ValueError(f"Invalid window: start ({start_str}) > end ({end_str})")

        # Check if target is within this window (inclusive boundaries)
        if start <= target <= end:
            return True

    return False


def _parse_date(date_str: str) -> datetime.date:
    """Parse and validate a date string in YYYY-MM-DD format.

    Raises ValueError if the date is malformed or impossible.
    """
    # Check basic format
    if not isinstance(date_str, str) or len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str}")

    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {date_str}")

    try:
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
    except ValueError:
        raise ValueError(f"Invalid date format: {date_str}")

    # Check for zero padding
    if parts[0] != str(year).zfill(4) or parts[1] != str(month).zfill(2) or parts[2] != str(day).zfill(2):
        raise ValueError(f"Invalid date format: {date_str}")

    # Validate the date using datetime (this handles leap years and impossible dates)
    try:
        return datetime(year, month, day).date()
    except ValueError:
        raise ValueError(f"Invalid calendar date: {date_str}")
